namespace EnterpriseDocumentIntelligence.BuildingBlocks.Domain;
public sealed class IdempotencyRecord{public Guid Id{get;private set;}=Guid.NewGuid();public string Key{get;private set;}=null!;public DateTimeOffset CreatedAt{get;private set;}=DateTimeOffset.UtcNow;public DateTimeOffset ExpiresAt{get;private set;}private IdempotencyRecord(){}public IdempotencyRecord(string key,TimeSpan ttl){if(string.IsNullOrWhiteSpace(key))throw new ArgumentException("Key is required",nameof(key));if(ttl<=TimeSpan.Zero)throw new ArgumentOutOfRangeException(nameof(ttl));Key=key;ExpiresAt=CreatedAt.Add(ttl);}public bool IsExpired(DateTimeOffset now)=>now>=ExpiresAt;}